-- ---------------------------------------------------------------------------
-- FIXTURE — the 105 / 112 calendar shape (2026 seeds; only the stamps
-- rewritten): WEEK 6 — QA @ QZ Thu 10-16 00:15Z (played, final), QB @ QY Sun
-- 10-18 17:00Z; QF @ QG FLEXED from Sun 10-18 13:00Z to 10-19 00:20Z. Every
-- other week: KC @ BUF one day after its start (week 5: Thu 10-08 04:00Z).
-- SUN = 10-18 16:00Z: after Thursday, before Sunday.
-- ---------------------------------------------------------------------------
update nfl_weeks w
set last_game_ends_at = case when w.week <= 5 then w.starts_at + interval '6 days'
                             when w.week = 6 then '2026-10-20 03:30:00+00'::timestamptz end,
    first_kickoff_at = null
where w.season = 2026;
delete from nfl_games where season = 2026;
insert into nfl_games (id, season, week, home_team, away_team, kickoff_at, status)
select 's-dummy-' || w.week, 2026, w.week, 'KC', 'BUF', w.starts_at + interval '1 day', case when w.week <= 5 then 'final' else 'scheduled' end
from nfl_weeks w where w.season = 2026 and w.week <= 14 and w.week <> 6;
insert into nfl_games (id, season, week, home_team, away_team, kickoff_at, status) values
