-- Post-reset race guard (067): today and tomorrow realtime.messages partitions.
do $part$
declare
  d date;
  part_name text;
begin
  foreach d in array array[current_date, current_date + 1] loop
    part_name := 'messages_' || to_char(d, 'YYYY_MM_DD');
    if not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
                   where n.nspname = 'realtime' and c.relname = part_name) then
      execute format('create table realtime.%I partition of realtime.messages for values from (%L) to (%L)',
                     part_name, d::timestamp, (d + 1)::timestamp);
    end if;
  end loop;
end
$part$;

-- A TRIAL runs one statement in a subtransaction that is then rolled back,
-- and returns its document and the league state it left — so the live body
-- and the pre-165 body start from the SAME state.
create function pg_temp.state() returns jsonb language sql as $$
  select jsonb_build_object(
    'rosters', (select jsonb_agg(jsonb_build_array(r.team_id, r.player_id, r.slot_key, r.ir_placed_week, r.ir_lock_until_week) order by r.team_id, r.player_id)
                from league_rosters r where r.league_id = 'b1130000-0000-4000-8000-000000000001'),
    'lineups', (select jsonb_agg(jsonb_build_object('team', tl.team_id, 'week', tl.week, 'slot_map', tl.slot_map, 'starters', tl.starters,
                                                    'bench', tl.bench, 'locked_at', tl.locked_at) order by tl.team_id, tl.week)
                from team_lineups tl join teams t on t.id = tl.team_id where t.league_id = 'b1130000-0000-4000-8000-000000000001'));
$$;
create function pg_temp.trial(p_sql text) returns jsonb language plpgsql as $$
declare
  v_doc   jsonb;
  v_state jsonb;
begin
  begin
    execute p_sql into v_doc;
    v_state := pg_temp.state();
    raise exception 'trial rolled back' using errcode = 'FST01';
  exception when sqlstate 'FST01' then
    null;
  end;
  return jsonb_build_object('doc', v_doc, 'state', v_state);
exception when others then
  return jsonb_build_object('error', sqlerrm, 'sqlstate', sqlstate);
end $$;
create temp table r113 (tag text primary key, r jsonb not null);
create function pg_temp.as_commish() returns void language sql as $$
  select set_config('request.jwt.claims', json_build_object('sub', '91130000-0000-4000-8000-000000000001', 'role', 'authenticated')::text, true);
$$;
select pg_temp.as_commish();

-- One commissioner edit of week p_week (EK Tango) through p_fn at p_at.
create function pg_temp.edit_sql(p_fn text, p_week int, p_map text, p_act int, p_at text) returns text language sql as $$
  select format('select %s(%L::uuid, %L::uuid, %s, %L::jsonb, %L::uuid, %L::timestamptz, null)', p_fn,
                'b1130000-0000-4000-8000-000000000001', 'c1130000-0000-4000-8000-000000000002', p_week, p_map,
                'a1130000-0000-4000-8000-' || lpad(p_act::text, 12, '0'), p_at)
$$;
-- The edit, then (p_then) the tick one minute later, or the MANAGER setting
-- his lineup five minutes later — the outcome returned beside the edit.
create function pg_temp.edit_then(p_fn text, p_map text, p_then text, p_mgr_map text) returns jsonb language plpgsql as $$
declare
  v_doc jsonb;
  v_out text;
begin
  execute pg_temp.edit_sql(p_fn, 6, p_map, 21, '2026-10-18 16:00:00+00') into v_doc;
  if p_then = 'tick' then
    perform set_config('request.jwt.claims', '', true);
    perform public.lineup_lock_tick('2026-10-18 16:01:00+00', 'b1130000-0000-4000-8000-000000000001');
    v_out := 'ticked';
  else
    perform set_config('request.jwt.claims', json_build_object('sub', '91130000-0000-4000-8000-000000000002', 'role', 'authenticated')::text, true);
    begin
      perform public.set_lineup_internal('b1130000-0000-4000-8000-000000000001', 'c1130000-0000-4000-8000-000000000002', 6,
                                         p_mgr_map::jsonb, 'a1130000-0000-4000-8000-000000000022', '2026-10-18 16:05:00+00', null);
      v_out := 'accepted';
    exception when others then
      v_out := sqlerrm;
    end;
  end if;
  perform pg_temp.as_commish();
  return jsonb_build_object('edit', v_doc, 'then', v_out);
end $$;

-- Renders a lineup row of the state: player@kickoff[flags],… | locked_at.
create function pg_temp.row_of(p_r jsonb, p_team text, p_week int) returns text language sql as $$
  select (select string_agg(coalesce(s ->> 'player_id', '-') || '@' || coalesce(s ->> 'kickoff_at', '-') || coalesce(s ->> 'flags', ''), ',' order by o)
          from jsonb_array_elements(l -> 'starters') with ordinality x(s, o)
          where s ->> 'player_id' is not null)
         || ' | locked_at ' || coalesce(l ->> 'locked_at', '-')
  from jsonb_array_elements(p_r -> 'state' -> 'lineups') l
  where l ->> 'team' = p_team and (l ->> 'week')::int = p_week
$$;
create function pg_temp.outcome(p_tag text) returns text language sql as $$
  select coalesce((select 'refused: ' || (r ->> 'error') from r113 where tag = p_tag and r ? 'error'),
                  (select 'landed' from r113 where tag = p_tag and r ? 'doc'), 'missing')
$$;

-- ---------------------------------------------------------------------------
-- B. F497 — a commissioner edit that KEEPS the played starters in place
--    (fills the empty qb:3 with EK Sun1): EK Rel (played Thursday, released,
--    no stat line) at qb:0, EK Trd (played Thursday, traded to a Sunday
--    team, no stat line) at qb:1, EK Flx (flexed game) at qb:2.
-- ---------------------------------------------------------------------------
update leagues set settings = '{"allow_illegal_lineups": false}'::jsonb where id = 'b1130000-0000-4000-8000-000000000001';
insert into r113 (tag, r)
select 'b1:' || f.side,
       pg_temp.trial(pg_temp.edit_sql(f.fn, 6, '{"qb:0": "s-rel", "qb:1": "s-trd", "qb:2": "s-flx", "qb:3": "s-sun1"}', 11, '2026-10-18 16:00:00+00'))
from (values ('live', 'public.commish_edit_lineup_internal'), ('pre', 'pg_temp.edit_pre165')) f(side, fn);
select is('live ' || pg_temp.outcome('b1:live') || ' | pre165 ' || pg_temp.outcome('b1:pre'),
  'live landed | pre165 refused: commish_edit_lineup: EK Rel (Thu, released) is on bye for week 6 and allow_illegal_lineups is off — slot "qb:0" is blocked at submit (§7.3.6); bench him, start someone who plays, or turn the setting on',
  'B1 allow_illegal_lineups OFF: a re-save that keeps a starter who played Thursday and was then released where he stands LANDS — before 165 his current team (none) read as a bye and the commissioner was refused (a timing read binding him)');

update leagues set settings = '{}'::jsonb where id = 'b1130000-0000-4000-8000-000000000001';
insert into r113 (tag, r)
select 'b2:' || f.side,
       pg_temp.trial(pg_temp.edit_sql(f.fn, 6, '{"qb:0": "s-rel", "qb:1": "s-trd", "qb:2": "s-flx", "qb:3": "s-sun1"}', 12, '2026-10-18 16:00:00+00'))
from (values ('live', 'public.commish_edit_lineup_internal'), ('pre', 'pg_temp.edit_pre165')) f(side, fn);
select is(
  (select pg_temp.row_of(r, 'c1130000-0000-4000-8000-000000000002', 6) from r113 where tag = 'b2:live'),
  's-rel@2026-10-16T00:15:00+00:00[],s-trd@2026-10-16T00:15:00+00:00[],s-flx@2026-10-19T00:20:00+00:00[],s-sun1@2026-10-18T17:00:00+00:00[] | locked_at 2026-10-16T00:15:00+00:00',
  'B2 the stored record: EK Rel (released) and EK Trd (traded to a Sunday team) keep the Thursday kickoff they PLAYED in, no bye flag, locked_at stays Thursday');
select is(
  (select pg_temp.row_of(r, 'c1130000-0000-4000-8000-000000000002', 6) from r113 where tag = 'b2:pre'),
  's-rel@-["bye"],s-trd@2026-10-18T17:00:00+00:00[],s-flx@2026-10-19T00:20:00+00:00[],s-sun1@2026-10-18T17:00:00+00:00[] | locked_at 2026-10-18T17:00:00+00:00',
  'B3 …where the pre-165 body wrote the r-e1 shape (released: no record, a bye flag) and the r-e4 shape (traded: his new team Sunday kickoff) and moved locked_at to Sunday');
select is(
  (select format('live %s %s | pre165 %s %s', l.r -> 'doc' -> 'locked_players_moved', l.r -> 'doc' -> 'bypassed', p.r -> 'doc' -> 'locked_players_moved', p.r -> 'doc' -> 'bypassed')
   from r113 l, r113 p where l.tag = 'b2:live' and p.tag = 'b2:pre'),
  'live [] [] | pre165 [] []',
  'B4 nobody was moved: the two played starters stayed where they stand, so the receipt names no lock walked past — under both bodies');

insert into r113 (tag, r)
select 'b5:' || f.side,
       pg_temp.trial(format('select pg_temp.edit_then(%L, %L, %L, null)', f.fn, '{"qb:0": "s-rel", "qb:1": "s-trd", "qb:2": "s-flx", "qb:3": "s-sun1"}', 'tick'))
from (values ('live', 'public.commish_edit_lineup_internal'), ('pre', 'pg_temp.edit_pre165')) f(side, fn);
select is(
  (select format('live %s || pre165 %s',
                 (select pg_temp.row_of(r, 'c1130000-0000-4000-8000-000000000002', 6) from r113 where tag = 'b5:live'),
                 (select pg_temp.row_of(r, 'c1130000-0000-4000-8000-000000000002', 6) from r113 where tag = 'b5:pre'))),
  'live s-rel@2026-10-16T00:15:00+00:00[],s-trd@2026-10-16T00:15:00+00:00[],s-flx@2026-10-19T00:20:00+00:00[],s-sun1@2026-10-18T17:00:00+00:00[] | locked_at 2026-10-16T00:15:00+00:00'
  || ' || pre165 s-rel@-["bye"],s-trd@2026-10-18T17:00:00+00:00[],s-flx@2026-10-19T00:20:00+00:00[],s-sun1@2026-10-18T17:00:00+00:00[] | locked_at 2026-10-18T17:00:00+00:00',
  'B5 the tick one minute later KEEPS the Thursday records the edit stored (157: a passed real kickoff stays) — and cannot restore the ones the pre-165 body erased');

insert into r113 (tag, r)
select 'b6:' || f.side,
       pg_temp.trial(format('select pg_temp.edit_then(%L, %L, %L, %L)', f.fn, '{"qb:0": "s-rel", "qb:1": "s-trd", "qb:2": "s-flx", "qb:3": "s-sun1"}', 'manager',
                            '{"qb:0": "s-sun2", "qb:1": "s-trd", "qb:2": "s-flx", "qb:3": "s-sun1"}'))
from (values ('live', 'public.commish_edit_lineup_internal'), ('pre', 'pg_temp.edit_pre165')) f(side, fn);
select is(
  (select format('live %s | pre165 %s', l.r -> 'doc' ->> 'then', p.r -> 'doc' ->> 'then') from r113 l, r113 p where l.tag = 'b6:live' and p.tag = 'b6:pre'),
  'live set_lineup: slot qb:0 is locked — EK Rel (Thu, released) kicked off at 2026-10-16T00:15:00+00:00 (lineup_record) and a locked slot''s player never moves (§11.2, lineup_lock = per_player_kickoff); every other unlocked slot stays editable | pre165 accepted',
  'B6 THE PLAYED LOCK SURVIVES THE EDIT (r-e1 shape): afterwards his manager cannot bench EK Rel — the lineup record says he played — where after the pre-165 edit the manager benched him in the week he played');
insert into r113 (tag, r)
select 'b7:' || f.side,
       pg_temp.trial(format('select pg_temp.edit_then(%L, %L, %L, %L)', f.fn, '{"qb:0": "s-rel", "qb:1": "s-trd", "qb:2": "s-flx", "qb:3": "s-sun1"}', 'manager',
                            '{"qb:0": "s-rel", "qb:1": "s-sun2", "qb:2": "s-flx", "qb:3": "s-sun1"}'))
from (values ('live', 'public.commish_edit_lineup_internal'), ('pre', 'pg_temp.edit_pre165')) f(side, fn);
select is(
  (select format('live %s | pre165 %s', l.r -> 'doc' ->> 'then', p.r -> 'doc' ->> 'then') from r113 l, r113 p where l.tag = 'b7:live' and p.tag = 'b7:pre'),
  'live set_lineup: slot qb:1 is locked — EK Trd (Thu, traded) kicked off at 2026-10-16T00:15:00+00:00 (lineup_record) and a locked slot''s player never moves (§11.2, lineup_lock = per_player_kickoff); every other unlocked slot stays editable | pre165 accepted',
  'B7 …and the r-e4 shape: EK Trd (traded to a Sunday team) stays locked for his manager after the edit; after the pre-165 edit his record read Sunday and the manager benched him');

