  'P1 allow_illegal_lineups OFF: a retroactive week-5 fix that keeps a since-released starter LANDS — before 165 his current team read as a bye and refused it');
update leagues set settings = '{}'::jsonb where id = 'b1130000-0000-4000-8000-000000000001';
