-- ---------------------------------------------------------------------------
-- C. The receipts are 164s (the fold) — and only the records differ
-- ---------------------------------------------------------------------------
insert into r113 (tag, r)
select 'c1:' || f.side,
       pg_temp.trial(pg_temp.edit_sql(f.fn, 6, '{"qb:0": "s-trd", "qb:1": "s-sun1", "qb:2": "s-flx", "ir:0": "s-out"}', 15, '2026-10-18 16:00:00+00'))
from (values ('live', 'public.commish_edit_lineup_internal'), ('pre', 'pg_temp.edit_pre165')) f(side, fn);
create function pg_temp.receipt(p_tag text) returns text language sql as $$
  select coalesce((select string_agg(format('%s %s->%s %s', m ->> 'player_id', m ->> 'from', coalesce(m ->> 'to', 'bench'), m ->> 'datum_arm'), ', ' order by m ->> 'player_id')
                   from r113, jsonb_array_elements(r -> 'doc' -> 'locked_players_moved') m where tag = p_tag), 'none')
         || ' ' || coalesce((select (r -> 'doc' -> 'bypassed')::text from r113 where tag = p_tag), (select r ->> 'error' from r113 where tag = p_tag))
$$;
select is('live ' || pg_temp.receipt('c1:live') || ' | pre165 ' || pg_temp.receipt('c1:pre'),
  'live s-rel qb:0->bench lineup_record, s-trd qb:1->qb:0 lineup_record ["per_player_kickoff_lock", "ir_lock_timing:s-out"] | pre165 s-rel qb:0->bench lineup_record, s-trd qb:1->qb:0 lineup_record ["per_player_kickoff_lock", "ir_lock_timing:s-out"]',
  'C1 the commissioner can still move played starters (he stands outside the lock): benching EK Rel and moving EK Trd are recorded exactly as 164 recorded them, and the IR timing lock for EK Out is named — one map now, the same receipt');
select is('live ' || pg_temp.receipt('p2:live') || ' | pre165 ' || pg_temp.receipt('p2:pre'),
  'live s-kc ->qb:1 nfl_games ["past_week", "closed_week:final", "per_player_kickoff_lock", "ir_lock_timing:s-out"] | pre165 s-kc ->qb:1 nfl_games ["past_week", "closed_week:final", "per_player_kickoff_lock", "ir_lock_timing:s-out"]',
  'C2 …and on a PAST week (the current-week map v_kick_cur feeds the IR timing receipt): the same receipt under both bodies');
select is(
  (select string_agg(x.tag || '=' || (x.a = x.b)::text, ' ' order by x.tag)
   from (select l.tag, l.r -> 'state' #- '{lineups}' as a, p.r -> 'state' #- '{lineups}' as b from r113 l join r113 p on p.tag = replace(l.tag, ':live', ':pre')
         where l.tag in ('b2:live', 'p2:live', 'c1:live')) x)
  || ' | ' ||
  (select string_agg(x.tag || '=' || (x.a = x.b)::text, ' ' order by x.tag)
   from (select l.tag,
                (select jsonb_agg(e - 'starters' - 'locked_at' order by e ->> 'team', e ->> 'week') from jsonb_array_elements(l.r -> 'state' -> 'lineups') e) as a,
                (select jsonb_agg(e - 'starters' - 'locked_at' order by e ->> 'team', e ->> 'week') from jsonb_array_elements(p.r -> 'state' -> 'lineups') e) as b
         from r113 l join r113 p on p.tag = replace(l.tag, ':live', ':pre') where l.tag in ('b2:live', 'p2:live', 'c1:live')) x)
  || ' | ' ||
  (select string_agg(x.tag || '=' || (x.a = x.b)::text, ' ' order by x.tag)
   from (select l.tag, l.r -> 'state' -> 'lineups' as a, p.r -> 'state' -> 'lineups' as b from r113 l join r113 p on p.tag = replace(l.tag, ':live', ':pre')
         where l.tag in ('b2:live', 'p2:live', 'c1:live')) x),
  'b2:live=true c1:live=true p2:live=true | b2:live=true c1:live=true p2:live=true | b2:live=false c1:live=false p2:live=false',
  'C3 ONLY THE RECORDS CHANGED: the rosters (IR placements included), and every lineup slot map and bench, are what the pre-165 body writes; the lineups differ only in starters[] records and locked_at');

